import Foundation

/// One typing language: its layout, long-press characters and dictionary details.
/// The catalog is generated by Scripts/build_languages.py into Languages.json.
public struct LanguagePack: Codable, Identifiable, Equatable {
    public let code: String
    public let name: String
    public let englishName: String
    public let shortTitle: String
    public let rows: [String]
    public let alternates: [String: [String]]
    public let hasDictionary: Bool
    public let autocorrect: Bool
    public let checker: String
    public let rightToLeft: Bool
    public let nextWords: [String: [String]]
    public var id: String { code }

    /// Scripts without capital letters (Arabic, Hebrew) need no shift key or auto-capitals.
    public var isCased: Bool { rows.joined().contains { $0.isLowercase } }
    public var locale: Locale { Locale(identifier: code == "pcm" ? "en_NG" : code) }
    /// BCP-47 tag reported to iOS for dictation and the host's spell checking.
    public var primaryLanguage: String { code == "pcm" ? "en-NG" : code }

    public func uppercased(_ text: String) -> String { text.uppercased(with: locale) }
    public func lowercased(_ text: String) -> String { text.lowercased(with: locale) }

    static let fallback = LanguagePack(code: "en", name: "English", englishName: "English", shortTitle: "EN",
                                       rows: ["qwertyuiop", "asdfghjkl", "zxcvbnm"], alternates: [:], hasDictionary: true,
                                       autocorrect: true, checker: "en_US", rightToLeft: false, nextWords: [:])
}

public enum LanguageCatalog {
    public static let all: [LanguagePack] = {
        guard let url = resourceBundle.url(forResource: "Languages", withExtension: "json"),
              let data = try? Data(contentsOf: url),
              let packs = try? JSONDecoder().decode([LanguagePack].self, from: data), !packs.isEmpty else { return [LanguagePack.fallback] }
        return packs
    }()
    private static let byCode = Dictionary(all.map { ($0.code, $0) }, uniquingKeysWith: { first, _ in first })

    public static func pack(_ code: String) -> LanguagePack { byCode[code] ?? byCode["en"] ?? LanguagePack.fallback }
    public static func contains(_ code: String) -> Bool { byCode[code] != nil }

    /// Languages from the phone's preferred-language list that the keyboard supports, in order.
    public static func deviceLanguages(_ preferred: [String] = Locale.preferredLanguages) -> [KeyboardLanguage] {
        var result: [KeyboardLanguage] = []
        for identifier in preferred {
            let code = String(identifier.split(separator: "-").first ?? "").lowercased()
            let mapped = code == "no" || code == "nn" ? "nb" : (code == "tl" ? "fil" : code)
            if contains(mapped), !result.contains(where: { $0.code == mapped }) { result.append(KeyboardLanguage(mapped)) }
        }
        return result
    }

    static var resourceBundle: Bundle {
        #if SWIFT_PACKAGE
        return Bundle.module
        #else
        return Bundle.main
        #endif
    }
}

/// A language the person types in, stored by its code (for example "en", "fr", "yo").
public struct KeyboardLanguage: Hashable, Codable, Identifiable {
    public let code: String
    public init(_ code: String) { self.code = LanguageCatalog.contains(code) ? code : "en" }

    public static let english = KeyboardLanguage("en")
    public static let yoruba = KeyboardLanguage("yo")
    public static let pidgin = KeyboardLanguage("pcm")
    public static var allCases: [KeyboardLanguage] { LanguageCatalog.all.map { KeyboardLanguage($0.code) } }

    public var id: String { code }
    public var rawValue: String { code }
    public var pack: LanguagePack { LanguageCatalog.pack(code) }
    public var title: String { pack.name }
    public var shortTitle: String { pack.shortTitle }

    public init(from decoder: Decoder) throws {
        let value = try decoder.singleValueContainer().decode(String.self)
        // v0.1 stored names instead of codes.
        let legacy = ["english": "en", "yoruba": "yo", "pidgin": "pcm"]
        self.init(legacy[value] ?? value)
    }
    public func encode(to encoder: Encoder) throws {
        var container = encoder.singleValueContainer()
        try container.encode(code)
    }
}
